Translate("esES", "tsunaman", {
	title = "Tsunaman",
	subtitle = "Enviado del Tribunal de las Mareas",
	found = "Refugio Roca del Sol",
	hint = [=[Busque al espíritu del agua que mora entre la Horda en Roca del Sol.]=],
	allegiance = "Tribunal de las Mareas · Horda",
	sections = {
		{
			title = "Resumen",
			text = [=[Tsunaman es un elemental de agua que ha venido al {link:sun-rock-retreat}Refugio Roca del Sol{/link} en una misión de guerra. El Tribunal de las Mareas lo envió a destruir a los elementales de fuego de {link:the-charred-vale}La Vega Carbonizada{/link}, pues Neptulon el Cazamareas, señor de los elementales de agua, quiere extinguir a sus primos de fuego. Su guerra, dice, lleva eras librándose en todos los planos.]=],
		},
		{
			title = "Importancia",
			text = [=[Tsunaman muestra que la ruina del {link:stonetalon-mountains}Espolón{/link} ha atraído la atención de poderes que están mucho más allá de las montañas. El fuego que los goblins prendieron en la vega se ha convertido en un frente de una guerra mucho más antigua entre los {link:elements}elementos{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Hace la guerra a los elementales de fuego de {link:the-charred-vale}La Vega Carbonizada{/link}.
• Informa de cada victoria al Tribunal de las Mareas.
• Envía aviso a {link:je-neu-sancrea}Je'neu Sancrea{/link} en la {link:zoram-gar-outpost}Avanzada de Zoram'gar{/link}, en {link:ashenvale}Vallefresno{/link}.]=],
		},
	},
	mentions = {
		{ text = "Guerra elemental" },
		{ text = "Problemas en las profundidades" },
	},
	bonds = {
		{ id = "tammra-windfield", name = "Tammra Windfield", note = "sana lo que el fuego quemó" },
	},
})

Translate("esES", "braug-dimspirit", {
	title = "Braug Dimspirit",
	subtitle = "Chamán de la Prueba del Saber",
	found = "Cerca de la boca del Espolón de El Paso del Espolón",
	hint = [=[Encuentre al sabio chamán que acampa cerca del túnel hacia Vallefresno.]=],
	allegiance = "Horda · Cima del Trueno",
	aliases = { "Braug" },
	sections = {
		{
			title = "Resumen",
			text = [=[Braug Dimspirit es un chamán de gran sabiduría que tiene su campamento cerca de {link:the-talondeep-path}El Paso del Espolón{/link}. Quienes buscan la Prueba del Saber acuden a él después de que {link:dorn-plainstalker}Dorn Plainstalker{/link}, de {link:thousand-needles}Las Mil Agujas{/link}, haya puesto a prueba sus cuerpos. Braug pone a prueba la mente. Cree que los goblins, los elfos de la noche y muchos otros pueblos comparten la culpa de las penurias de {link:kalimdor}Kalimdor{/link}, no solo los orcos y los {link:forsaken}Renegados{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Braug mantiene una vieja tradición de la {link:horde}Horda{/link}: que un héroe debe conocer la historia del mundo, no solo cómo luchar en él.]=],
		},
		{
			title = "Hazañas",
